declare namespace SigApi {
    interface View {
        /**
         * Gets the view index
         * 
         * @returns {number}
         */
        getIndex(): number
        /**
         * Gets the view isDefault flag
         * 
         * @returns {boolean}
         */
        isDefault(): boolean
        /**
         * Gets the view name
         * 
         * @returns {string}
         */
        getName(): string
        /**
         * Gets the view instanceId
         * 
         * @returns {string}
         */
        getInstanceId(): string
        /**
         * Gets the view width
         * 
         * @returns {string}
         */
        getWidth(): string
        /**
         * Gets the view height
         * 
         * @returns {string}
         */
        getHeight(): string
    }
}
